//! HTTP request tool.use std::collections::HashMap;use std::net::{IpAddr, Ipv4Addr, SocketAddr};use std::sync::Arc;use std::time::Duration;use async_trait::async_trait;use futures::StreamExt;use reqwest::Client;use crate::context::JobContext;use crate::safety::LeakDetector;use crate::secrets::SecretsStore;use crate::tools::tool::{ApprovalRequirement, Tool, ToolError, ToolOutput, require_str};use crate::tools::wasm::{InjectedCredentials, SharedCredentialRegistry, inject_credential};#[cfg(feature = "html-to-markdown")]use crate::tools::builtin::convert_html_to_markdown;/// Maximum response body size for text responses (5 MB).////// 5 MB is large enough for typical JSON API responses and moderate HTML pages,/// but small enough to prevent OOM from malicious or runaway servers.  The WASM/// HTTP wrapper uses the same limit for consistency.const MAX_RESPONSE_SIZE: usize = 5 * 1024 * 1024;/// Maximum response body size when saving to disk via `save_to` (50 MB).////// Larger limit for file downloads since the body is written to disk, not held/// in memory for LLM context. Matches the WASM attachment size cap.const MAX_SAVE_TO_SIZE: usize = 50 * 1024 * 1024;/// Default request timeout when the caller does not provide one.const DEFAULT_TIMEOUT_SECS: u64 = 30;/// Maximum allowed request timeout to bound resource usage from LLM-controlled inputs.const MAX_TIMEOUT_SECS: u64 = 300;/// Maximum number of redirects to follow for simple GET requests.const MAX_REDIRECTS: usize = 3;/// Descriptive User-Agent so public APIs don't reject bare requests.const USER_AGENT: &str = concat!(    "IronClaw-Agent/",    env!("CARGO_PKG_VERSION"),    " (https://github.com/nearai/ironclaw)");/// Tool for making HTTP requests.////// Each request builds a per-request [`Client`] with DNS pinning to prevent/// TOCTOU DNS rebinding attacks.  The hostname is resolved once, validated/// against the SSRF blocklist, and then pinned via/// [`reqwest::ClientBuilder::resolve_to_addrs`] so that reqwest connects/// directly to the pre-validated IPs without a second DNS lookup.pub struct HttpTool {    credential_registry: Option<Arc<SharedCredentialRegistry>>,    secrets_store: Option<Arc<dyn SecretsStore + Send + Sync>>,}impl HttpTool {    /// Create a new HTTP tool.    pub fn new() -> Self {        Self {            credential_registry: None,            secrets_store: None,        }    }    /// Attach a credential registry and secrets store for auto-injection.    pub fn with_credentials(        mut self,        registry: Arc<SharedCredentialRegistry>,        secrets_store: Arc<dyn SecretsStore + Send + Sync>,    ) -> Self {        self.credential_registry = Some(registry);        self.secrets_store = Some(secrets_store);        self    }}/// Validate and resolve a `save_to` path, ensuring it stays under `/tmp/`.////// Uses `path_utils::validate_path` with `/tmp` as the base directory to catch/// traversal attacks like `/tmp/../../etc/passwd` and symlink escapes./// Creates parent directories only after validation succeeds.fn validate_save_to_path(save_to: &str) -> Result<std::path::PathBuf, ToolError> {    // Quick prefix check before doing any fs work    if !save_to.starts_with("/tmp/") {        return Err(ToolError::InvalidParameters(            "save_to path must be under /tmp/".to_string(),        ));    }    // Validate path BEFORE creating directories to prevent traversal-based    // directory creation outside /tmp (e.g. `/tmp/../../etc/passwd`).    let tmp_base = std::path::Path::new("/tmp");    let validated = crate::tools::builtin::path_utils::validate_path(save_to, Some(tmp_base))?;    // Only create parent directories for the validated (safe) path    if let Some(parent) = validated.parent() {        std::fs::create_dir_all(parent).map_err(|e| {            ToolError::ExecutionFailed(format!("failed to create directory: {}", e))        })?;    }    Ok(validated)}/// Parse and validate a URL without DNS resolution.////// Checks scheme (HTTPS only), rejects localhost and private/link-local IP/// literals.  Does **not** resolve hostnames -- use [`validate_and_resolve_url`]/// for the full DNS-pinning flow that eliminates the TOCTOU rebinding window.pub(crate) fn validate_url(url: &str) -> Result<reqwest::Url, ToolError> {    let parsed = reqwest::Url::parse(url)        .map_err(|e| ToolError::InvalidParameters(format!("invalid URL: {}", e)))?;    if parsed.scheme() != "https" {        return Err(ToolError::NotAuthorized(            "only https URLs are allowed".to_string(),        ));    }    let host = parsed        .host_str()        .ok_or_else(|| ToolError::InvalidParameters("URL missing host".to_string()))?;    let host_lower = host.to_lowercase();    if host_lower == "localhost" || host_lower.ends_with(".localhost") {        return Err(ToolError::NotAuthorized(            "localhost is not allowed".to_string(),        ));    }    // Check literal IP addresses    if let Ok(ip) = host.parse::<IpAddr>()        && is_disallowed_ip(&ip)    {        return Err(ToolError::NotAuthorized(            "private or local IPs are not allowed".to_string(),        ));    }    Ok(parsed)}/// Resolve DNS for a validated URL and check every resolved address against/// the SSRF blocklist.////// Returns the resolved [`SocketAddr`]s so that callers can pin the hostname/// via [`reqwest::ClientBuilder::resolve_to_addrs`], preventing a DNS rebinding/// attack where a second, independent resolution (inside reqwest) returns a/// different -- potentially private -- IP after our validation pass.pub(crate) async fn validate_and_resolve_url(    url: &reqwest::Url,) -> Result<Vec<SocketAddr>, ToolError> {    let host = url        .host_str()        .ok_or_else(|| ToolError::InvalidParameters("URL missing host".to_string()))?;    let port = url.port_or_known_default().unwrap_or(443);    let addrs: Vec<SocketAddr> = tokio::net::lookup_host(format!("{}:{}", host, port))        .await        .map_err(|e| {            ToolError::ExternalService(format!("DNS resolution failed for '{}': {}", host, e))        })?        .collect();    if addrs.is_empty() {        return Err(ToolError::ExternalService(format!(            "DNS resolution for '{}' returned no addresses",            host        )));    }    for addr in &addrs {        if is_disallowed_ip(&addr.ip()) {            return Err(ToolError::NotAuthorized(format!(                "hostname '{}' resolves to disallowed IP {}",                host,                addr.ip()            )));        }    }    Ok(addrs)}/// Build a reqwest [`Client`] that pins the given hostname to the/// pre-validated resolved addresses, preventing any second DNS lookup.pub(crate) fn build_pinned_client(    host: &str,    resolved_addrs: &[SocketAddr],    timeout: Duration,    redirect_policy: reqwest::redirect::Policy,) -> Result<Client, ToolError> {    let builder = Client::builder()        .timeout(timeout)        .redirect(redirect_policy)        .user_agent(USER_AGENT)        .resolve_to_addrs(host, resolved_addrs);    builder        .build()        .map_err(|e| ToolError::ExternalService(format!("failed to build HTTP client: {}", e)))}/// Check whether an IPv4 address falls in a disallowed range (private,/// loopback, link-local, multicast, unspecified, or cloud metadata).fn is_disallowed_ipv4(v4: &Ipv4Addr) -> bool {    v4.is_private()        || v4.is_loopback()        || v4.is_link_local()        || v4.is_multicast()        || v4.is_unspecified()        || *v4 == Ipv4Addr::new(169, 254, 169, 254)        || (v4.octets()[0] == 100 && (v4.octets()[1] & 0xC0) == 64)}fn is_disallowed_ip(ip: &IpAddr) -> bool {    match ip {        IpAddr::V4(v4) => is_disallowed_ipv4(v4),        IpAddr::V6(v6) => {            // Catch IPv4-mapped IPv6 addresses (e.g. ::ffff:169.254.169.254)            // that would bypass IPv4-only checks.            if let Some(v4) = v6.to_ipv4_mapped()                && is_disallowed_ipv4(&v4)            {                return true;            }            v6.is_loopback()                || v6.is_unique_local()                || v6.is_unicast_link_local()                || v6.is_multicast()                || v6.is_unspecified()        }    }}#[cfg(feature = "html-to-markdown")]/// Heuristic: treat as HTML if the `Content-Type` header contains `text/html`.fn is_html_response(headers: &HashMap<String, String>) -> bool {    headers        .iter()        .find(|(k, _)| k.eq_ignore_ascii_case("content-type"))        .map(|(_, v)| v.to_lowercase().contains("text/html"))        .unwrap_or(false)}